fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and select the Lists application, then click 'Operations' in its TOP navigation bar (next to 'Lists', 'Shared With Me', 'Categories'); the 'List Operations' page opens. Then follow these steps IN ORDER: (1) in the left 'Selected Operands' panel click the 'Search lists to add...' box (a dropdown of your lists opens; you may type 'VIP' to narrow it) and click 'VIP Members' — it appears as an operand chip labelled with entity 'People' and the centre Venn area shows a circle; (2) click the 'Search lists to add...' box again (it now offers only People lists) and click 'Recent Sign-ups' — the counter shows 2/4, the Venn diagram shows two overlapping circles, and a 'Quick Operations' group appears below the operands; (3) click 'Union All' and confirm the right 'Results' panel shows 'Union (All Records)' with an 'N records' count (expected 8), then click 'Intersection' and confirm it shows 'Intersection (Common Records)' with a count (expected 3). Do not use the 'Search views to add...' box and do not click 'Create New List', 'Add to List' or 'Compute & Save'. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Adding 'VIP Members' and then 'Recent Sign-ups' from the 'Search lists to add...' picker places two People operand chips in the Selected Operands panel (counter 2/4)",
    "With two operands the Venn diagram renders two overlapping circles and a 'Quick Operations' group (Union All / Intersection / Unique Each) appears; clicking 'Union All' or 'Intersection' makes the Results panel show the operation label ('Union (All Records)' or 'Intersection (Common Records)') with an 'N records' count",
    "No error messages, blank screens, or crash pages"
  ]
}
